const staticData = $getWorkflowStaticData('global');
staticData.efasProcessedLeads = staticData.efasProcessedLeads || {};

let lead = {};
try { lead = $('Lead Detayını Yeniden Çek').first().json.result || {}; } catch (e) {}

let contact = {};
try { contact = $('Kişi Detayını Çek').first().json.result || {}; } catch (e) {}

let webhook = {};
try { webhook = $('Webhook - EFAS Yaşamkent').first().json || {}; } catch (e) {}

const body = webhook.body || {};
const query = webhook.query || {};

const leadId = (
  lead.ID ||
  body["document_id[2]"] ||
  body["data[FIELDS][ID]"] ||
  body.id ||
  query.id ||
  "0"
).toString().replace("LEAD_", "");

if (leadId === "0") return [];

// Aynı lead için mükerrer webhook gelirse 1 saat içinde ikinci SMS'i engeller.
const now = Date.now();
const previousRun = staticData.efasProcessedLeads[leadId];
if (previousRun && (now - previousRun) < 3600000) {
  return [];
}
staticData.efasProcessedLeads[leadId] = now;

function titleCase(str) {
  if (!str) return "";
  return String(str)
    .toLocaleLowerCase("tr-TR")
    .split(" ")
    .filter(Boolean)
    .map(word =>
      word.charAt(0).toLocaleUpperCase("tr-TR") + word.slice(1)
    )
    .join(" ");
}

function getFirstValue(value) {
  if (!value) return "";
  if (Array.isArray(value) && value[0]) {
    return value[0].VALUE || value[0].value || "";
  }
  if (typeof value === "object") {
    return value.VALUE || value.value || "";
  }
  return String(value);
}

function normalizeTurkeyPhone(rawPhone) {
  let digits = String(rawPhone || "").replace(/\D/g, "");

  if (digits.startsWith("0090")) digits = digits.slice(2);

  if (digits.startsWith("90") && digits.length === 12) {
    return { e164: "+" + digits, sms: digits, valid: true };
  }

  if (digits.startsWith("0") && digits.length === 11) {
    digits = "90" + digits.slice(1);
    return { e164: "+" + digits, sms: digits, valid: true };
  }

  if (digits.length === 10 && digits.startsWith("5")) {
    digits = "90" + digits;
    return { e164: "+" + digits, sms: digits, valid: true };
  }

  return { e164: "", sms: digits, valid: false };
}

const rawName =
  lead.NAME ||
  contact.NAME ||
  body.name ||
  body.NAME ||
  body["data[FIELDS][NAME]"] ||
  "";

const rawLastName =
  lead.LAST_NAME ||
  contact.LAST_NAME ||
  body.last_name ||
  body.LAST_NAME ||
  body["data[FIELDS][LAST_NAME]"] ||
  "";

const firstName = titleCase(String(rawName).trim());
const fullName = (
  firstName + " " + titleCase(String(rawLastName).trim())
).trim();

const rawPhone =
  body["data[FIELDS][PHONE][0][VALUE]"] ||
  body["data[FIELDS][PHONE]"] ||
  body["PHONE[0][VALUE]"] ||
  body.phone ||
  body.Phone ||
  body.PHONE ||
  body.telefon ||
  body.Telefon ||
  body.TELEFON ||
  body.mobile ||
  body.MOBILE ||
  body.gsm ||
  body.GSM ||
  query.phone ||
  query.PHONE ||
  getFirstValue(lead.PHONE) ||
  getFirstValue(contact.PHONE) ||
  "";

const phone = normalizeTurkeyPhone(rawPhone);

const email =
  body["data[FIELDS][EMAIL][0][VALUE]"] ||
  body["EMAIL[0][VALUE]"] ||
  body.email ||
  body.Email ||
  body.EMAIL ||
  body.eposta ||
  body.EPOSTA ||
  query.email ||
  getFirstValue(lead.EMAIL) ||
  getFirstValue(contact.EMAIL) ||
  "";

const sourceTitle =
  lead.TITLE ||
  body.title ||
  body.TITLE ||
  "";

return [{
  json: {
    lead_id: leadId,
    first_name: firstName,
    full_name: fullName || "Değerli Müşterimiz",
    raw_phone: rawPhone,
    sms_phone: phone.sms,
    phone_e164: phone.e164,
    phone_valid: phone.valid,
    phone_error: phone.valid
      ? ""
      : `Geçerli telefon numarası bulunamadı. Gelen değer: ${rawPhone || "BOŞ"}`,
    email: email,
    lead_title: sourceTitle,
    status_id: lead.STATUS_ID || "",
    project_name: "EFAS Yaşamkent"
  }
}];

